-- FORMED teaching library: verified YouTube lessons. Run once in the Supabase SQL Editor; safe to re-run.
-- Video IDs, titles, channels, years and durations were read from YouTube on 2026-11-06.
-- Everything stays RESEARCH_CANDIDATE and hidden from users until an admin approves it.
-- Descriptions and reflection questions are drafts written without watching the videos: reviewers must check them.
BEGIN;

UPDATE teaching_resources SET review_status = 'UNAVAILABLE'
WHERE id::text LIKE '44444444-%' AND review_status = 'RESEARCH_CANDIDATE';

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

DELETE FROM curriculum_path_lessons
WHERE path_id IN (SELECT id FROM curriculum_paths WHERE code IN ('A','B','C','D'));

